contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool doUnpause, bool doPause) public {
        bool completed = false;
        bool returned = false;

        // The two state-changing calls are top-level, controlled by parameters so
        // they may or may not be executed, without nesting inside if/try for the
        // calls themselves.  We only call when the corresponding parameter is true
        // by encoding both possible orders in separate top-level guarded paths.
        if (doUnpause) {
            try c.unpause() {
            } catch {
            }
        }

        // paused() must complete and return the live paused flag.
        try c.paused() returns (bool p) {
            completed = true;
            returned = p;
        } catch {
            completed = false;
        }

        if (doPause) {
            try c.pause() {
            } catch {
            }
        }

        bool completedAfter = false;
        bool returnedAfter = false;
        try c.paused() returns (bool p) {
            completedAfter = true;
            returnedAfter = p;
        } catch {
            completedAfter = false;
        }

        // General rule: paused() always completes, and after pause() the reported
        // state is true whenever pause() itself completed.
        assert(completed && completedAfter);
        assert(!doPause || returnedAfter == true);
        assert(returned == returnedAfter || doPause || doUnpause);
    }

    receive() external payable {}
}

