contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool doPause) public {
        bool beforeVal;
        beforeVal = c.paused();
        bool beforeCompleted = true;
        try c.paused() returns (bool p) {
            beforeVal = p;
            beforeCompleted = true;
        } catch {
            beforeCompleted = false;
        }

        require(beforeCompleted);

        bool pauseSucceeded;
        if (doPause) {
            try c.pause() {
                pauseSucceeded = true;
            } catch {
                pauseSucceeded = false;
            }
        }

        bool afterVal;
        bool afterCompleted;
        try c.paused() returns (bool p) {
            afterVal = p;
            afterCompleted = true;
        } catch {
            afterCompleted = false;
        }

        require(afterCompleted);

        assert(afterVal == c.paused());
    }

    receive() external payable {}
}

