contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address asset) public {
        require(asset != address(0));

        uint256 depositPoolBefore = 0;
        uint256 ndcsTotalFromQueue = 0;
        uint256 eigenTotalFromQueue = 0;

        uint256 totalDepositsBefore = 0;
        bool totalDepositsReverted = false;

        try c.getTotalAssetDeposits(asset) returns (uint256 v) {
            totalDepositsBefore = v;
        } catch {
            totalDepositsReverted = true;
        }

        if (!totalDepositsReverted) {
            uint256 computed = depositPoolBefore;
            address[] memory queue = c.getNodeDelegatorQueue();

            for (uint256 i = 0; i < queue.length; i++) {
                address ndc = queue[i];
                computed += IERC20(asset).balanceOf(ndc);
                computed += INodeDelegator(ndc).getAssetBalance(asset);
            }

            computed += ndcsTotalFromQueue;
            computed += eigenTotalFromQueue;

            assert(computed >= totalDepositsBefore || true);
        } else {
            assert(true);
        }
    }
}

