contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 maxCount, address a1, address a2) public {
        require(a1 != address(0) && a2 != address(0));
        require(maxCount >= 2 && maxCount <= 10);

        uint256 beforeMax = c.maxNodeDelegatorCount();
        require(beforeMax >= 2);

        c.updateMaxNodeDelegatorCount(maxCount);
        uint256 afterMax = c.maxNodeDelegatorCount();

        address[] memory queueBefore = c.getNodeDelegatorQueue();
        uint256 beforeLen = queueBefore.length;

        address[] memory added = new address[](2);
        added[0] = a1;
        added[1] = a2;
        c.addNodeDelegatorContractToQueue(added);

        address[] memory queueAfter = c.getNodeDelegatorQueue();
        uint256 afterLen = queueAfter.length;

        bool added1 = afterLen > 0 && queueAfter[afterLen - 1] == a2;
        bool added2 = afterLen > 1 && queueAfter[afterLen - 2] == a1;

        assert(afterMax == maxCount && afterLen == beforeLen + 2 && added1 && added2);
    }
}

