    }

    function run(address[] calldata newAddrs, bool addThem) public {
        address[] memory beforeQueue = c.getNodeDelegatorQueue();
        uint256 beforeLength = beforeQueue.length;

        if (addThem) {
            c.addNodeDelegatorContractToQueue(newAddrs);
        }

        address[] memory afterQueue = c.getNodeDelegatorQueue();

        uint256 expectedAdded;
        for (uint256 i = 0; i < newAddrs.length; i++) {
            if (addThem && newAddrs[i] != address(0)) {
                expectedAdded++;
            }
        }

        assert(afterQueue.length == beforeLength + expectedAdded);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata newAddrs) public {
        uint256 maxCount = c.maxNodeDelegatorCount();
        uint256 existingLength = c.getNodeDelegatorQueue().length;
        require(existingLength + newAddrs.length <= maxCount, "would exceed max count");

        uint256 expectedNonZero;
        for (uint256 i = 0; i < newAddrs.length; i++) {
            if (newAddrs[i] != address(0)) {
                expectedNonZero++;
            }
        }
        require(expectedNonZero == newAddrs.length, "all new addresses must be non-zero");

        c.addNodeDelegatorContractToQueue(newAddrs);

        address[] memory afterQueue = c.getNodeDelegatorQueue();

        assert(afterQueue.length == existingLength + newAddrs.length);
    }
}

