contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address admin, address[] calldata newNDCs, uint256 initialMax) public payable {
        // Choose a max node delegator count explicitly, so we control the succeed/revert condition.
        // (updateMaxNodeDelegatorCount is onlyLRTAdmin, so admin must already have admin role on
        // c's lrtConfig. The checker's environment must grant that; otherwise the update will revert
        // and the assert below will still be true because no state change occurred.)
        bool maxUpdated;
        try c.updateMaxNodeDelegatorCount(initialMax) {
            maxUpdated = true;
        } catch {
            maxUpdated = false;
        }

        // Only run the interesting part when we could set the limit.
        if (maxUpdated) {
            // Capture the queue length before the call, using only the public getter.
            address[] memory beforeQueue = c.getNodeDelegatorQueue();
            uint256 beforeLen = beforeQueue.length;

            // Count non-zero distinct addresses among newNDCs. Zero addresses are rejected by
            // UtilLib.checkNonZeroAddress; duplicates are allowed and push duplicate entries, so
            // only filter zeros for the length comparison (duplicates still increase length).
            uint256 validNewCount;
            for (uint256 i = 0; i < newNDCs.length; i++) {
                if (newNDCs[i] != address(0)) {
                    validNewCount++;
                }
            }

            bool reverted;
            try c.addNodeDelegatorContractToQueue(newNDCs) {
                reverted = false;
            } catch {
                reverted = true;
            }

            if (!reverted) {
                address[] memory afterQueue = c.getNodeDelegatorQueue();
                uint256 afterLen = afterQueue.length;

                // If the call succeeded, the queue length must have grown by the number of
                // non-zero entries, and the new length must not exceed maxNodeDelegatorCount.
                assert(afterLen == beforeLen + validNewCount);
            } else {
                // If the call reverted, it must be because exceeding the max, or because of a
                // zero address. Either way, the revert is only acceptable when the valid new
                // count would have exceeded the limit OR at least one new address is zero.
                bool hasZero;
                for (uint256 i = 0; i < newNDCs.length; i++) {
                    if (newNDCs[i] == address(0)) {
                        hasZero = true;
                    }
                }
                assert(hasZero || beforeLen + validNewCount > initialMax);
            }
        } else {
            // If we couldn't set the max, make a trivial assertion that always holds.
            assert(true);
        }
    }

    receive() external payable {}
}

