        address oldConfig = address(c.lrtConfig());
        // Freshly deployed C is uninitialized; calling updateLRTConfig would revert in the role check
        // (lrtConfig is address(0), so no DEFAULT_ADMIN_ROLE can be held by this contract).
        require(oldConfig != address(0), "contract must be initialized first");

        bool callerIsAdmin;
        (bool ok, bytes memory data) = oldConfig.staticcall(
            abi.encodeWithSignature("hasRole(bytes32,address)", bytes32(0), address(this))
        );
        if (ok && data.length >= 32) {
            callerIsAdmin = abi.decode(data, (bool));
        }

        bool reverted;
        try c.updateLRTConfig(newLrtConfig) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!callerIsAdmin) {
            assert(reverted);
        } else {
            assert(address(c.lrtConfig()) == newLrtConfig);
        }
    }
}

