contract InvMutTest {
    C c;
    address public supportedAsset;
    address public unsupportedAsset;

    constructor(C _c) {
        c = _c;
        supportedAsset = address(0x1111111111111111111111111111111111111111);
        unsupportedAsset = address(0x2222222222222222222222222222222222222222);
    }

    function run(uint256 arbitraryInput) public {
        require(arbitraryInput >= 0);

        bool reverted;
        uint256 assetLyingInDepositPool;
        uint256 assetLyingInNDCs;
        uint256 assetStakedInEigenLayer;

        try c.getAssetDistributionData(unsupportedAsset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(false);
        } else {
            try c.getAssetDistributionData(supportedAsset) returns (uint256 a, uint256 b, uint256 d) {
                assetLyingInDepositPool = a;
                assetLyingInNDCs = b;
                assetStakedInEigenLayer = d;
                reverted = false;
            } catch {
                reverted = true;
            }

            if (reverted) {
                assert(false);
            } else {
                uint256 expectedDepositPoolBalance = IERC20(supportedAsset).balanceOf(address(c));
                assert(assetLyingInDepositPool == expectedDepositPoolBalance);
            }
        }
    }
}

